def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        # If it's a datetime.time object, convert to ISO format string
        if hasattr(value, 'isoformat'):
            return value.isoformat()
        # If it's already a string, return as is
        elif isinstance(value, str):
            return value
        # If it's a tuple or list representing (hour, minute, second, ...), convert to time
        elif isinstance(value, (tuple, list)):
            from datetime import time
            if len(value) >= 3:
                t = time(value[0], value[1], value[2])
                if len(value) > 3:
                    t = t.replace(microsecond=value[3])
                return t.isoformat()
            else:
                raise ValueError("Invalid time tuple/list")
        else:
            # Try to convert to string
            return str(value)
    except Exception as e:
        raise ValueError(f"Cannot dehydrate time value: {e}")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        return {
            'x': value.x,
            'y': value.y
        }
    except AttributeError:
        # If value doesn't have x and y attributes, try to convert it
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return {
                'x': value[0],
                'y': value[1]
            }
        else:
            raise ValueError("Invalid Point value: expected an object with x and y attributes or a sequence of at least two elements")

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self._data.keys())
    except AttributeError:
