def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            # Check if the specific version is supported
            if protocol_version in cls._protocol_handlers:
                return {protocol_version: cls._protocol_handlers[protocol_version]}
            else:
                return {}
        else:
            # Return all available protocol handlers
            return dict(cls._protocol_handlers)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key {key} not found")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._values)

    result = []
    for key in keys:
        if isinstance(key, int):
            if 0 <= key < len(self._values):
                result.append(self._values[key])
            else:
                raise IndexError(f"Index {key} out of range")
        elif isinstance(key, str):
            if key in self._keys:
                idx = self._keys.index(key)
                result.append(self._values[idx])
            else:
                raise KeyError(f"Key {key} not found")
        else:
            raise TypeError(f"Invalid key type: {type(key)}")

    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume self has attributes:
    # self._fields: list of field names
    # self._values: list of values corresponding to self._fields
    # Or perhaps self is a record with .fields and .values or similar.
    # Let's assume a common pattern: self._fields and self._values

    if not keys:
        return dict(zip(self._fields, self._values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Check bounds
            if key < 0:
                # Negative index: check if within range
                if key >= -len(self._fields):
                    field_name = self._fields[key]
                    value = self._values[key]
                else:
                    raise IndexError("index out of range")
            else:
                if key >= len(self._fields):
                    raise IndexError("index out of range")
                field_name = self._fields[key]
                value = self._values[key]
            result[field_name] = value
        elif isinstance(key, str):
            # Check if key exists in fields
            if key in self._fields:
                idx = self._fields.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
        else:
            # If key is neither int nor str, treat as key (string-like) or raise?
            # The docstring says "indexes or keys". Let's assume keys are strings.
            # If it's not an int, treat as a key.
            if key in self._fields:
                idx = self._fields.index(key)
                result[key] = self._values[idx]
            else:
                result[key] = None
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16-bit unsigned integer")
    last_two_bytes = self.data[-2:]
    self.data = self.data[:-2]
    return int.from_bytes(last_two_bytes, byteorder='big')

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ()
    parts = s.split('.')
    result = []
    for part in parts:
        if not part:
            continue
        try:
            num = int(part)
        except ValueError:
            raise ValueError(f"Invalid version component: {part!r}")
        result.append(num)
    return tuple(result)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock is not None:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def _lru_cache_wrapper(maxsize, typed):
        def decorator(func):
            from collections import OrderedDict
            from functools import wraps
            from threading import RLock

            cache = OrderedDict()
            cache_get = cache.get
            cache_len = len
            cache_popitem = cache.popitem
            cache_clear = cache.clear
            cache_move_to_end = cache.move_to_end
            lock = RLock()
            hits = misses = 0
            maxsize_local = maxsize

            @wraps(func)
            def wrapper(*args, **kwargs):
                nonlocal hits, misses
                if typed:
                    key = (args, frozenset(kwargs.items()))
                else:
                    key = (args, frozenset(kwargs.items()))
                with lock:
                    try:
                        value = cache_get(key)
                    except TypeError:
                        # unhashable arguments
                        return func(*args, **kwargs)
                    else:
                        if value is not None:
                            cache_move_to_end(key)
                            hits += 1
                            return value
                misses += 1
                value = func(*args, **kwargs)
                with lock:
                    if maxsize_local is not None:
                        if cache_len(cache) >= maxsize_local:
                            cache_popitem(last=False)
                    cache[key] = value
                return value

            def cache_info():
                with lock:
                    return {'hits': hits, 'misses': misses, 'maxsize': maxsize_local, 'currsize': cache_len(cache)}

            def cache_clear():
                with lock:
                    cache_clear()
                    nonlocal hits, misses
                    hits = misses = 0

            wrapper.cache_info = cache_info
            wrapper.cache_clear = cache_clear
            return wrapper
        return decorator
    if maxsize is None:
        return _lru_cache_wrapper(None, typed)
    elif maxsize is not None:
        if not isinstance(maxsize, int):
            raise TypeError('Expected maxsize to be an integer or None')
        if maxsize < 0:
            raise ValueError('Expected maxsize to be non-negative')
    return _lru_cache_wrapper(maxsize, typed)

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(self, *args, **kwargs):
            k = key(self, args, kwargs)
            if lock is not None:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(self, *args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(self, *args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if all:
        return [(name, self.__dict__[name].__doc__) for name in dir(self) if not name.startswith('_')]
    else:
        return [(name, self.__dict__[name].__doc__) for name in dir(self) if not name.startswith('_') and name in self.__dict__]

