def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Check if seq is a Source sequence
        if hasattr(seq, 'is_source') and seq.is_source():
            return False

        # Check if seq is a FillRequest element
        if hasattr(seq, 'is_fill_request') and seq.is_fill_request():
            return True

        # Check if seq contains at least one FillRequest element
        if hasattr(seq, '__iter__'):
            for item in seq:
                if hasattr(item, 'is_fill_request') and item.is_fill_request():
                    return True

        return False
    except Exception:
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
