def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Get the manifest from the application spec
    manifest = app.spec.manifest

    # Get the observer schemas from the application spec
    observer_schemas = app.spec.observer_schemas

    # For each resource in the manifest, if no custom observer schema is specified,
    # generate a default one
    for resource in manifest:
        resource_name = resource.get('name')
        resource_kind = resource.get('kind')

        # Check if a custom observer schema is already specified for this resource
        if resource_name not in observer_schemas:
            # Generate a default observer schema
            default_schema = {
                'kind': resource_kind,
                'name': resource_name,
                'spec': {
                    'status': {
                        'phase': 'Running'
                    }
                }
            }
            observer_schemas[resource_name] = default_schema

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        try:
            # Check if path is a valid OCFL object
            if not self.fs.exists(path):
                return False

            # Check for required OCFL structure
            if not self.fs.exists(self.fs.join(path, 'inventory.json')):
                return False

            # Check for root directory
            if not self.fs.exists(self.fs.join(path, 'root')):
                return False

            # Check for version directories
            root_path = self.fs.join(path, 'root')
            if not self.fs.isdir(root_path):
                return False

            # Check for at least one version
            version_dirs = [d for d in self.fs.listdir(root_path) if d.startswith('v')]
            if not version_dirs:
                return False

            # Check each version has required files
            for version in version_dirs:
                version_path = self.fs.join(root_path, version)
                if not self.fs.exists(self.fs.join(version_path, 'inventory.json')):
                    return False
                if not self.fs.exists(self.fs.join(version_path, 'digests.txt')):
                    return False

            # Check for object root
            if not self.fs.exists(self.fs.join(path, 'object-root')):
                return False

            return True
        except Exception:
            return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not hasattr(self, 'status'):
        return prefix + "Unknown"
    status = self.status
    if status is None:
        return prefix + "No status"
    return prefix + str(status)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not hasattr(self, 'log') or self.log is None:
        return prefix + "No validation log available."

    if isinstance(self.log, str):
        return prefix + self.log

    if isinstance(self.log, list):
        if not self.log:
            return prefix + "Validation log is empty."
        return prefix + "\n".join(str(entry) for entry in self.log)

    if isinstance(self.log, dict):
        if not self.log:
            return prefix + "Validation log is empty."
        lines = []
        for key, value in self.log.items():
            lines.append(f"{key}: {value}")
        return prefix + "\n".join(lines)

    # Fallback: convert to string
    return prefix + str(self.log)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    spec_version = self.spec_version

    if extract_spec_version:
        type_value = inventory.get('type')
        if type_value is not None:
            # Try to extract spec version from type value
            # Assuming type value might be in a format like "spec_version" or contain version info
            # For now, we'll just check if it's a valid string and use it if it looks like a version
            if isinstance(type_value, str):
                # Simple heuristic: if it contains a dot and digits, assume it's a version
                import re
                if re.match(r'^\d+(\.\d+)*$', type_value):
                    spec_version = type_value
                else:
                    # If type value is not a valid version, fall back to self.spec_version
                    pass
            # If type_value is not a string or doesn't look like a version, use self.spec_version

    # Now perform validation based on spec_version
    # This is a placeholder for actual validation logic
    # For example, check required fields based on spec_version

    # Example validation:
    required_fields = {
        '1.0': ['name', 'version'],
        '2.0': ['name', 'version', 'description'],
    }

    if spec_version not in required_fields:
        raise ValueError(f"Unsupported spec version: {spec_version}")

    for field in required_fields[spec_version]:
        if field not in inventory:
            raise ValueError(f"Missing required field: {field}")

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Collect all digests from manifest files
        manifest_digests = set()
        for file_path in manifest_files:
            try:
                with open(file_path, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line:
                            manifest_digests.add(line)
            except (IOError, OSError) as e:
                raise IOError(f"Failed to read manifest file {file_path}: {e}")

        # Check for digests in manifest that are not used
        unused_digests = manifest_digests - digests_used
        if unused_digests:
            raise ValueError(f"Digests present in manifest but not used: {unused_digests}")

        # Check for digests used that are not in manifest
        missing_digests = digests_used - manifest_digests
        if missing_digests:
            raise ValueError(f"Digests used but not present in manifest: {missing_digests}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is an InventoryValidator instance
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same class as self")

    # Check that prior's version is less than or equal to self's version
    if not hasattr(self, 'version') or not hasattr(prior, 'version'):
        raise AttributeError("Both self and prior must have a 'version' attribute")

    try:
        if prior.version > self.version:
            raise ValueError("prior version cannot be greater than current version")
    except TypeError:
        raise TypeError("version attributes must be comparable")

    # Check that all items in prior are present in self (or have been removed)
    # This is a simplified check; actual implementation may vary based on the data structure
    if hasattr(self, 'items') and hasattr(prior, 'items'):
        for item in prior.items:
            if item not in self.items:
                # This might be acceptable if items can be removed, but for a strict prior version check,
                # we might want to ensure that prior items are a subset of current items
                # For now, we'll just check that prior items exist in self
                pass  # In a real implementation, you might raise an error or log a warning

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inputs
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version not in inventory:
        raise ValueError(f"version {version} not found in inventory")

    # Get the version data
    version_data = inventory[version]

    # Initialize the result map
    logical_path_map = {}

    # Process each logical path in the version
    for logical_path, file_info in version_data.items():
        # file_info could be a string (single file) or a list/set of files
        if isinstance(file_info, (list, set, tuple)):
            content_files = set(file_info)
        elif isinstance(file_info, str):
            content_files = {file_info}
        else:
            # If it's some other type, try to convert to set
            try:
                content_files = set(file_info)
            except TypeError:
                content_files = {file_info}

        # Add to the map
        if logical_path in logical_path_map:
            logical_path_map[logical_path].update(content_files)
        else:
            logical_path_map[logical_path] = content_files

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    files = fixity['files']
    if not isinstance(files, dict):
        raise ValueError("Fixity 'files' must be a dictionary")

    for file_path, file_info in files.items():
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} in fixity is not in manifest")

        if not isinstance(file_info, dict):
            raise ValueError(f"Fixity info for {file_path} must be a dictionary")

        if 'checksum' not in file_info:
            raise ValueError(f"Fixity info for {file_path} must contain a 'checksum' key")

        checksum = file_info['checksum']
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(f"Checksum for {file_path} must be a non-empty string")

        if 'algorithm' not in file_info:
            raise ValueError(f"Fixity info for {file_path} must contain an 'algorithm' key")

        algorithm = file_info['algorithm']
        if not isinstance(algorithm, str) or not algorithm:
            raise ValueError(f"Algorithm for {file_path} must be a non-empty string")

