def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import sys

    # If commands is a string, split it into a list
    if isinstance(commands, str):
        commands = commands.split()

    # If args is a string, split it into a list
    if isinstance(args, str):
        args = args.split()

    # Combine commands and args
    full_command = commands + args

    # Set up environment
    if env is None:
        env = os.environ.copy()
    else:
        env = os.environ.copy()
        env.update(env)

    # Set up stdout and stderr
    stdout = None
    stderr = None
    if hide_stderr:
        stderr = subprocess.DEVNULL

    # Run the command
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")
            if cwd:
                print(f"Working directory: {cwd}")

        process = subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=stdout,
            stderr=stderr,
            universal_newlines=True
        )

        # Wait for the process to complete
        stdout_output, stderr_output = process.communicate()

        if verbose:
            if stdout_output:
                print(f"STDOUT: {stdout_output}")
            if stderr_output and not hide_stderr:
                print(f"STDERR: {stderr_output}")

        return process.returncode

    except FileNotFoundError:
        if verbose:
            print(f"Command not found: {full_command[0]}")
        return 127
    except Exception as e:
        if verbose:
            print(f"Error running command: {e}")
        return 1

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    try:
        # Iterate through the hierarchy
        for obj in self.hierarchy:
            num_objects += 1
            is_valid = True

            if validate_objects:
                # Check if the object is valid
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj} is not valid")

            if check_digests and is_valid:
                # Check if the digest is correct
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj} has invalid digest")

            if is_valid:
                good_objects += 1
    except Exception as e:
        if show_warnings:
            print(f"Error during validation: {e}")

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Split by dots
    parts = version.split('.')

    # Check if all parts are numeric (allowing leading zeros)
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Invalid version component: {part}")

    # Determine if the version uses zero-prefixed format
    # A version is zero-prefixed if any part has leading zeros (and length > 1)
    zero_prefixed = any(len(part) > 1 and part[0] == '0' for part in parts)

    # Convert to integers
    nums = [int(part) for part in parts]

    # Increment the last component
    nums[-1] += 1

    # Format back to string
    if zero_prefixed:
        # Preserve the original width of each part
        result_parts = []
        for i, (orig_part, num) in enumerate(zip(parts, nums)):
            width = len(orig_part)
            result_parts.append(str(num).zfill(width))
        return '.'.join(result_parts)
    else:
        return '.'.join(str(num) for num in nums)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of version directory names")

    # Assume self has attributes like:
    # self.root_inventory: dict mapping content paths to digests
    # self.version_inventories: dict mapping version dir names to inventory dicts
    # self.content_digests: dict to store digests different from root inventory

    if not hasattr(self, 'root_inventory'):
        self.root_inventory = {}
    if not hasattr(self, 'version_inventories'):
        self.version_inventories = {}
    if not hasattr(self, 'content_digests'):
        self.content_digests = {}

    for version_dir in version_dirs:
        if not isinstance(version_dir, str):
            raise TypeError(f"Each version directory name must be a string, got {type(version_dir)}")

        # Check if inventory exists for this version
        if version_dir not in self.version_inventories:
            # No inventory found for this version
            # This is a SHOULD, so we might just log a warning or skip
            continue

        inventory = self.version_inventories[version_dir]

        # Compare with root inventory
        for path, digest in inventory.items():
            if path in self.root_inventory:
                root_digest = self.root_inventory[path]
                if digest != root_digest:
                    # Record the difference
                    self.content_digests[path] = digest
            else:
                # Path not in root inventory, record it
                self.content_digests[path] = digest

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple")

    # Ensure all bug_ids are valid (positive integers)
    for bug_id in bug_ids:
        if not isinstance(bug_id, int) or bug_id <= 0:
            raise ValueError("All bug_ids must be positive integers")

    # Create a copy of params to avoid modifying the original
    amended_params = params.copy()

    # Add or update the bug_ids in the params
    amended_params['bug_ids'] = list(bug_ids)

    return amended_params

def parser_flags(parser):
