        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0

    # Build a mapping from character to its index in the alphabet
    char_to_index = {char: idx for idx, char in enumerate(alphabet)}

    result = 0
    base = len(alphabet)

    for char in string:
        if char not in char_to_index:
            raise ValueError(f"Character '{char}' is not in the given alphabet")
        result = result * base + char_to_index[char]

    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def addignored(ignored):
    try:
        # Run git command to get ignored files
        result = subprocess.run(['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
                                capture_output=True, text=True, check=True)

        # Split the output into a list of file names
        files = result.stdout.strip().split('\n')

        # Filter out empty strings and sort the list
        files = [f for f in files if f]
        files.sort()

        # Join the file names into a single string separated by commas
        return ','.join(files)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.stderr}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {str(e)}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Check if the host is a known localhost name
        if host in ('localhost', '127.0.0.1', '::1'):
            return True

        # Try to resolve the hostname to an IP address
        addr_info = socket.getaddrinfo(host, None)
        for family, socktype, proto, canonname, sockaddr in addr_info:
            ip = sockaddr[0]
            if ip in ('127.0.0.1', '::1'):
                return True
        return False
    except socket.gaierror:
        # If the host cannot be resolved, it's not localhost
        return False
    except Exception:
        # For any other unexpected errors, return False
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Check if we're on Windows
        if os.name != 'nt':
            return False

        # Check if we're in a git bash environment
        # Git bash typically sets the MSYSTEM environment variable
        if 'MSYSTEM' in os.environ:
            return True

        # Alternative check: look for git bash specific environment variables
        if 'GIT_BASH' in os.environ:
            return True

        # Check if the shell is bash and we're on Windows
        if 'SHELL' in os.environ and 'bash' in os.environ['SHELL'].lower():
            return True

        return False
    except Exception:
        return False

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # The matcher is expected to be a string in the format "name" or "name:default"
    # We need to parse it to extract the name and optional default value.

    if not isinstance(matcher, str):
        raise TypeError("matcher must be a string")

    # Split by the first colon to separate name and default
    if ':' in matcher:
        name, default = matcher.split(':', 1)
    else:
        name = matcher
        default = None

    # Get the value from environment
    value = os.environ.get(name)

    if value is not None:
        return value
    elif default is not None:
        return default
    else:
        raise EnvironmentError(f"Environment variable '{name}' is not set and no default value provided")

