def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging

    import os

    import json

    import yaml

    import re

    def _apply_overrides(config, overrides):
        """Recursively apply overrides to the config dictionary."""
        result = config.copy()
        for key, value in overrides.items():
            if isinstance(value, dict) and key in result and isinstance(result[key], dict):
                result[key] = _apply_overrides(result[key], value)
            else:
                result[key] = value
        return result

    def _resolve_env_vars(config):
        """Recursively resolve environment variables in string values."""
        if isinstance(config, dict):
            return {k: _resolve_env_vars(v) for k, v in config.items()}
        elif isinstance(config, list):
            return [_resolve_env_vars(item) for item in config]
        elif isinstance(config, str):
            # Resolve environment variables in the format ${VAR_NAME} or $VAR_NAME
            def replace_env(match):
                var_name = match.group(1) or match.group(2)
                return os.environ.get(var_name, match.group(0))

            # Match ${VAR_NAME} or $VAR_NAME
            pattern = r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)'
            return re.sub(pattern, replace_env, config)
        else:
            return config
    if not isinstance(config_filenames, (list, tuple)):
        config_filenames = [config_filenames]

    if overrides is None:
        overrides = {}
    elif not isinstance(overrides, dict):
        overrides = {}

    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            if not isinstance(filename, str):
                raise ValueError(f"Filename must be a string, got {type(filename)}")

            if not os.path.exists(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            with open(filename, 'r') as f:
                content = f.read()

            # Determine file type by extension
            ext = os.path.splitext(filename)[1].lower()

            if ext in ('.json',):
                config = json.loads(content)
            elif ext in ('.yaml', '.yml'):
                config = yaml.safe_load(content)
            else:
                # Try JSON first, then YAML
                try:
                    config = json.loads(content)
                except json.JSONDecodeError:
                    config = yaml.safe_load(content)

            if config is None:
                config = {}

            if not isinstance(config, dict):
                raise ValueError(f"Configuration file {filename} must contain a dictionary, got {type(config)}")

            # Apply overrides
            if overrides:
                config = _apply_overrides(config, overrides)

            # Resolve environment variables if requested
            if resolve_env:
                config = _resolve_env_vars(config)

            configs[filename] = config

        except Exception as e:
            logger = logging.getLogger(__name__)
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=__file__,
                lno=0,
                msg=f"Error loading configuration file {filename}: {str(e)}",
                args=(),
                exc_info=(type(e), e, e.__traceback__)
            )
            errors.append(record)

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol_version must be a tuple")
            # Check if the specific version is supported
            if protocol_version in cls._protocol_handlers:
                return {protocol_version: cls._protocol_handlers[protocol_version]}
            else:
                return {}
        else:
            # Return all available protocol handlers
            return dict(cls._protocol_handlers)

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        try:
            # Convert each raw value to a Bookmark object
            bookmarks = [cls._from_raw_value(value) for value in values]
            return cls(bookmarks)
        except Exception as e:
            raise ValueError(f"Failed to create Bookmarks from raw values: {e}")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple, str, bytes)):
        return seq, type(seq)
    elif hasattr(seq, '__iter__') and not isinstance(seq, (str, bytes)):
        # It's an iterable but not a basic sequence type
        # Convert to list
        return list(seq), list
    else:
        # Not iterable, wrap in a list
        return [seq], list

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a class")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a class")

    # Check if candidate is a subclass of iface or is iface itself
    if not issubclass(candidate, iface):
        if tentative:
            return False
        else:
            raise TypeError(f"{candidate.__name__} is not a subclass of {iface.__name__}")

    # If tentative, just return True if it's a subclass
    if tentative:
        return True

    # For non-tentative, we might want to check if all abstract methods are implemented
    # This is a simplified check; a full implementation would inspect abstract methods
    try:
        # Try to instantiate to see if it's abstract (this is a heuristic)
        # But we don't want to actually instantiate, so we check for abstract methods
        import inspect
        abstract_methods = []
        for name, method in inspect.getmembers(candidate):
            if inspect.isfunction(method) and getattr(method, '__isabstractmethod__', False):
                abstract_methods.append(name)

        if abstract_methods:
            raise TypeError(f"{candidate.__name__} has unimplemented abstract methods: {', '.join(abstract_methods)}")
    except Exception:
        # If we can't determine, we'll just pass
        pass

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise TypeError("bases must be a non-empty tuple or list")

    # If explicit metaclass is provided, use it
    if explicit_mc is not None:
        return explicit_mc

    # Find the most derived metaclass from the bases
    metaclasses = []
    for base in bases:
        if isinstance(base, type):
            metaclasses.append(type(base))
        elif hasattr(base, '__class__'):
            metaclasses.append(type(base))

    if not metaclasses:
        return type

    # Find the most derived metaclass
    # A metaclass M1 is more derived than M2 if M1 is a subclass of M2
    most_derived = metaclasses[0]
    for mc in metaclasses[1:]:
        if issubclass(mc, most_derived):
            # mc is more derived or equal
            if mc is not most_derived:
                most_derived = mc
        elif issubclass(most_derived, mc):
            # most_derived is more derived, keep it
            pass
        else:
            # Incompatible metaclasses
            raise TypeError("metaclasses %s and %s are incompatible" % (most_derived, mc))

    return most_derived

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError("dictionary is empty")
    key = random.choice(list(self.keys()))
    value = self[key]
    del self[key]
    return (key, value)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check if it's a public message
        if hasattr(request, 'public_message') and request.public_message:
            return 'public_message'

        # Check if it's a private message
        if hasattr(request, 'private_message') and request.private_message:
            return 'private_message'

        # Check if it's a legacy payload
        if hasattr(request, 'legacy_payload') and request.legacy_payload:
            return 'legacy_payload'

        # If none of the above, return None or raise an exception
        return None

    except Exception as e:
        # Handle any unexpected errors
        raise ValueError(f"Failed to identify request: {str(e)}")

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check if the request has a path that starts with /_matrix
        if hasattr(request, 'path') and request.path.startswith('/_matrix'):
            return True
        # Check if the request has a URL that contains /_matrix
        if hasattr(request, 'url') and '/_matrix' in request.url:
            return True
        # Check if the request has a header indicating Matrix
        if hasattr(request, 'headers'):
            headers = request.headers
            if 'X-Matrix-Request' in headers:
                return True
        return False
    except Exception:
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    try:
        return dt.strftime("%Y-%m-%d %H:%M:%S")
    except (AttributeError, TypeError) as e:
        raise ValueError(f"Invalid datetime object: {e}")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    # A valid tag should contain only alphanumeric characters and underscores
    # and should not start with a digit
    if not tag[0].isalpha() and tag[0] != '_':
        return False
    for char in tag:
        if not (char.isalnum() or char == '_'):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            # If the tag already exists, convert to list
            if not isinstance(result[tag], list):
                result[tag] = [result[tag]]
            result[tag].append(child)
        else:
            result[tag] = child
    return result

