    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")

    file_names = []
    for directory in settings_dirs:
        if not isinstance(directory, str):
            raise TypeError("Each element in settings_dirs must be a string")
        file_name = os.path.join(directory, spec_option)
        file_names.append(file_name)

    return file_names

