def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content is required")

        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Invalid YAML content: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a dictionary")

        # Define required fields (example, adjust as needed)
        required_fields = ['name', 'version']

        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing required field: {field}")

        return data

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("YAML file path is required")

        try:
            with open(yaml_file, 'r') as f:
                data = yaml.safe_load(f)
        except FileNotFoundError:
            raise IRValidatorException(f"File not found: {yaml_file}")
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file must contain a dictionary")

        # Validate required fields
        required_fields = ['name', 'version', 'description']
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing required field: {field}")

        return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if 'include' not in parser_dict:
            return parser_dict

        include_list = parser_dict['include']
        if not isinstance(include_list, list):
            raise ValueError("'include' must be a list of group names")

        for group_name in include_list:
            if not isinstance(group_name, str):
                raise ValueError("Each include entry must be a string")
            if group_name not in self._groups:
                raise ValueError(f"Unknown group: {group_name}")
            group_dict = self._groups[group_name]
            # Recursively resolve includes in the group
            group_dict = self._include_groups(group_dict)
            # Merge the group dict into parser_dict
            for key, value in group_dict.items():
                if key in parser_dict:
                    if isinstance(parser_dict[key], dict) and isinstance(value, dict):
                        parser_dict[key].update(value)
                    elif isinstance(parser_dict[key], list) and isinstance(value, list):
                        parser_dict[key].extend(value)
                    else:
                        parser_dict[key] = value
                else:
                    parser_dict[key] = value

        # Remove the 'include' key after processing
        del parser_dict['include']
        return parser_dict

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {}
    for arg in self.args:
        if hasattr(arg, 'deprecated') and arg.deprecated:
            deprecated_args[arg.name] = arg.deprecated
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Define deprecated arguments
    deprecated_args = {
        'old_flag': 'new_flag',
        'legacy_option': 'modern_option'
    }

    # Check for deprecated arguments in cli_args
    for arg, replacement in deprecated_args.items():
        if arg in cli_args:
            print(f"Warning: Argument '{arg}' is deprecated. Please use '{replacement}' instead.")

    # Check for deprecated arguments in answer_file_args
    for arg, replacement in deprecated_args.items():
        if arg in answer_file_args:
            print(f"Warning: Argument '{arg}' in answer file is deprecated. Please use '{replacement}' instead.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # Assuming there is a dictionary or attribute that stores parser options
        # For example, self.parser_options might be a dict mapping command names to option specs
        if not hasattr(self, 'parser_options'):
            raise AttributeError("Parser options not initialized")

        if command_name not in self.parser_options:
            raise ValueError(f"Command '{command_name}' not found in parser options")

        return self.parser_options[command_name]
    except Exception as e:
        raise e

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        if not isinstance(command_name, str) or not isinstance(argument_name, str):
            raise TypeError("command_name and argument_name must be strings")

        # Assuming there is a structure like self.options or self.command_options
        # that maps command names to their option specifications.
        # For example: self.options = {command_name: {argument_name: spec, ...}, ...}

        if not hasattr(self, 'options') or not isinstance(self.options, dict):
            raise AttributeError("The 'options' attribute is not a dictionary")

        if command_name not in self.options:
            raise KeyError(f"Command '{command_name}' not found in options")

        command_options = self.options[command_name]

        if not isinstance(command_options, dict):
            raise TypeError(f"Options for command '{command_name}' must be a dictionary")

        if argument_name not in command_options:
            raise KeyError(f"Argument '{argument_name}' not found in options for command '{command_name}'")

        return command_options[argument_name]

    except (TypeError, KeyError, AttributeError) as e:
        # Depending on the expected behavior, we might return None or re-raise
        # For now, let's return None to indicate the option spec was not found
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if not hasattr(self, 'silent_args'):
        self.silent_args = []
    if args is None:
        return self.silent_args
    if isinstance(args, dict):
        return [k for k in args.keys() if k in self.silent_args]
    elif isinstance(args, (list, tuple)):
        return [a for a in args if a in self.silent_args]
    else:
        return [args] if args in self.silent_args else []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, 'requires_args'):
        return True
    for arg in self.requires_args:
        if arg not in args:
            raise ValueError(f"Missing required argument: {arg}")
    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if isinstance(arg, (str, list, tuple, bytes)):
            if len(arg) > self.length:
                raise ValueError(f"Argument length {len(arg)} exceeds specified length {self.length}")
        elif isinstance(arg, dict):
            if len(arg) > self.length:
                raise ValueError(f"Argument length {len(arg)} exceeds specified length {self.length}")
        else:
            # For other types, we might not be able to check length, or it's not applicable
            pass

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg.choices is not None:
            if arg.value not in arg.choices:
                raise ValueError(f"Invalid value '{arg.value}' for argument '{arg.name}'. Must be one of {arg.choices}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Assuming self has attributes min_value and max_value
    # and args is a dictionary or object with attributes
    # We'll handle both cases

    if not hasattr(self, 'min_value') or not hasattr(self, 'max_value'):
        raise AttributeError("Object must have 'min_value' and 'max_value' attributes")

    # If args is a dictionary
    if isinstance(args, dict):
        for key, value in args.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key '{key}' must be a number")
            if value < self.min_value or value > self.max_value:
                raise ValueError(f"Value for key '{key}' ({value}) is out of range [{self.min_value}, {self.max_value}]")
    # If args is an object with attributes
    elif hasattr(args, '__dict__'):
        for key, value in vars(args).items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for attribute '{key}' must be a number")
            if value < self.min_value or value > self.max_value:
                raise ValueError(f"Value for attribute '{key}' ({value}) is out of range [{self.min_value}, {self.max_value}]")
    # If args is a single value
    elif isinstance(args, (int, float)):
        if args < self.min_value or args > self.max_value:
            raise ValueError(f"Value ({args}) is out of range [{self.min_value}, {self.max_value}]")
    else:
        raise TypeError("args must be a dictionary, an object with attributes, or a numeric value")

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is None:
            return vars_dict

        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError("extra_vars must be a list or tuple")

        for item in extra_vars:
            if not isinstance(item, str):
                raise TypeError("Each item in extra_vars must be a string")

            if '=' not in item:
                raise ValueError(f"Invalid extra-var format: {item}. Expected 'key=value'")

            key, value = item.split('=', 1)
            key = key.strip()
            value = value.strip()

            if not key:
                raise ValueError(f"Empty key in extra-var: {item}")

            vars_dict[key] = value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import shlex
    import os

    # Build the command
    cmd = ['ansible-playbook']

    # Add verbosity if specified
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose > 0:
                cmd.append('-' + 'v' * verbose)
        elif isinstance(verbose, str):
            cmd.append('-' + verbose)

    # Add extra vars if specified
    if extra_vars is not None:
        if isinstance(extra_vars, dict):
            # Convert dict to key=value pairs
            for key, value in extra_vars.items():
                cmd.append(f'--extra-vars {key}={value}')
        elif isinstance(extra_vars, str):
            cmd.append(f'--extra-vars {extra_vars}')

    # Add ansible_args if specified
    if ansible_args is not None:
        if isinstance(ansible_args, dict):
            for key, value in ansible_args.items():
                if value is None:
                    cmd.append(f'--{key}')
                else:
                    cmd.append(f'--{key} {value}')
        elif isinstance(ansible_args, str):
            cmd.append(ansible_args)

    # Add the playbook path
    cmd.append(playbook_path)

    # Get the environment
    env = os.environ.copy()

    # Set up the environment for Ansible
    # This is a simplified version; in practice, you might need to set more variables
    # based on the ir_workspace and ir_plugin

    try:
        # Run the command
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            check=False
        )

        # Return the result
        return {
            'returncode': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr
        }
    except Exception as e:
        return {
            'returncode': -1,
            'stdout': '',
            'stderr': str(e)
        }

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import os
    import tempfile

    # Build the command
    cmd = ['ansible-playbook']

    # Add extra vars if provided
    if vars_dict:
        # Create a temporary file for the vars
        with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.json') as f:
            json.dump(vars_dict, f)
            vars_file = f.name
        cmd.extend(['-e', '@' + vars_file])

    # Add the cli_args
    cmd.extend(cli_args)

    # Set up environment
    env = os.environ.copy()

    # If ir_workspace provides any environment variables, add them
    if ir_workspace and hasattr(ir_workspace, 'get_env'):
        try:
            workspace_env = ir_workspace.get_env()
            if workspace_env:
                env.update(workspace_env)
        except Exception:
            pass

    # If ir_plugin provides any environment variables, add them
    if ir_plugin and hasattr(ir_plugin, 'get_env'):
        try:
            plugin_env = ir_plugin.get_env()
            if plugin_env:
                env.update(plugin_env)
        except Exception:
            pass

    # Run the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            timeout=3600  # 1 hour timeout
        )

        # Clean up the temporary vars file
        if vars_dict and 'vars_file' in locals():
            try:
                os.unlink(vars_file)
            except Exception:
                pass

        # Return the result
        return {
            'returncode': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr
        }

    except subprocess.TimeoutExpired:
        # Clean up the temporary vars file
        if vars_dict and 'vars_file' in locals():
            try:
                os.unlink(vars_file)
            except Exception:
                pass
        raise
    except Exception as e:
        # Clean up the temporary vars file
        if vars_dict and 'vars_file' in locals():
            try:
                os.unlink(vars_file)
            except Exception:
                pass
        raise

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Define a mapping of argument names to their expected types
        # This is a simplified example; in a real scenario, this would be
        # more comprehensive and possibly data-driven.
        type_mapping = {
            'port': int,
            'timeout': int,
            'retries': int,
            'verbose': bool,
            'debug': bool,
            'dry_run': bool,
            'max_connections': int,
            'buffer_size': int,
            'rate_limit': float,
            'threshold': float,
        }

        # Iterate over the values_dict and convert values based on the type mapping
        for key, value in list(values_dict.items()):
            if key in type_mapping:
                target_type = type_mapping[key]
                try:
                    if target_type is bool:
                        # Handle boolean conversion specially
                        if isinstance(value, str):
                            value_lower = value.lower()
                            if value_lower in ('true', '1', 'yes', 'on'):
                                values_dict[key] = True
                            elif value_lower in ('false', '0', 'no', 'off'):
                                values_dict[key] = False
                            else:
                                # If it's not a recognizable boolean string, leave it as is or raise an error
                                # For now, we'll leave it as the original string
                                pass
                        else:
                            values_dict[key] = bool(value)
                    else:
                        values_dict[key] = target_type(value)
                except (ValueError, TypeError):
                    # If conversion fails, leave the value as is or handle the error
                    # For now, we'll leave the value unchanged
                    pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml

    # Define the path to the plugin spec file
    spec_file = os.path.join(plugin_dir, 'plugin_spec.json')
    spec_file_yaml = os.path.join(plugin_dir, 'plugin_spec.yaml')

    # Try to load the spec from JSON first
    if os.path.exists(spec_file):
        try:
            with open(spec_file, 'r') as f:
                spec = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from JSON: {e}")
    # If JSON doesn't exist, try YAML
    elif os.path.exists(spec_file_yaml):
        try:
            with open(spec_file_yaml, 'r') as f:
                spec = yaml.safe_load(f)
        except (yaml.YAMLError, IOError) as e:
            raise ValueError(f"Failed to load plugin spec from YAML: {e}")
    else:
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    # Flatten the dictionary
    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'config.json')

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")

    # Normalize the paths to ensure consistent comparison
    # We'll use os.path.normpath to handle different path separators
    import os

    # Ensure root ends with a separator for proper prefix matching
    # But we need to be careful with the root itself
    if root == '':
        raise ValueError("Root cannot be empty")

    # Normalize both paths
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)

    # Check if path starts with root
    # We need to ensure we're matching at a path boundary
    if norm_path == norm_root:
        return ''

    # Check if path starts with root followed by a separator
    # On Windows, we need to handle both / and \
    if os.sep == '\\':
        # Windows: check for both / and \
        if norm_path.startswith(norm_root + '\\') or norm_path.startswith(norm_root + '/'):
            # Find the length of root and the separator
            if norm_path.startswith(norm_root + '\\'):
                return norm_path[len(norm_root) + 1:]
            else:
                return norm_path[len(norm_root) + 1:]
        else:
            raise ValueError(f"Path {path} does not start with root {root}")
    else:
        # Unix-like: check for /
        if norm_path.startswith(norm_root + '/'):
            return norm_path[len(norm_root) + 1:]
        else:
            raise ValueError(f"Path {path} does not start with root {root}")
